def solve(inp):
    from collections import Counter
    h,w=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    cells=[(r,c) for r in range(h) for c in range(w) if inp[r][c]!=bg]
    def isolated(r,c):
        return all(inp[rr][cc]==bg for rr in range(r-1,r+2) for cc in range(c-1,c+2) if (rr,cc)!=(r,c) and 0<=rr<h and 0<=cc<w)
    markers=[(r,c) for r,c in cells if isolated(r,c)]
    sprite=[(r,c) for r,c in cells if (r,c) not in markers]
    rs=[r for r,c in sprite]; cs=[c for r,c in sprite]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    H=r1-r0+1; W=c1-c0+1
    sg=[[inp[r0+i][c0+j] for j in range(W)] for i in range(H)]
    out=[row[:] for row in inp]
    for r,c in markers:
        for i in range(H):
            for j in range(W):
                rr,cc=r-H//2+i, c-W//2+j
                if 0<=rr<h and 0<=cc<w and sg[i][j]!=bg:
                    out[rr][cc]=sg[i][j]
    return out
